window.TT_LEX={"beaver": {"zh": "河狸", "phrases": [["eager beaver", "做事特别积极的人"], ["busy as a beaver", "像河狸一样忙碌"]], "scene": ["ai", "A beaver opened a \"Dam Good Repair Shop.\" Business was great — every customer said, \"Wood you fix my house?\"", "一只河狸开了一家\"超棒水坝修理店\"。生意好极了——每位顾客都说：\"你能帮我修修房子吗？\"（wood 和 would 读音很像哦）"], "dlg": ["Look at that animal with the big flat tail! What is it?", "It's a beaver. It slaps its tail on the water!", "It's a pencil. I write with it every day."], "us": "/ˈbivɚ/"}, "tooth": {"zh": "牙齿（复数 teeth）", "phrases": [["sweet tooth", "爱吃甜食"], ["brush your teeth", "刷牙"]], "scene": ["ai", "Benny the beaver never needed a toothbrush. \"My teeth are orange,\" he smiled, \"so I can chew a whole tree for breakfast!\"", "河狸本尼从来不用牙刷。\"我的牙是橙色的，\"他笑着说，\"所以早餐能啃掉一整棵树！\""], "dlg": ["Why do beavers need such big front teeth?", "Because they chew wood all day long!", "Because they like to sing in the rain."], "us": "/tuθ/"}, "wetland": {"zh": "湿地", "phrases": [["protect the wetlands", "保护湿地"], ["wetland birds", "湿地鸟类"]], "scene": ["ai", "A frog wrote a review of her wetland home: \"Five stars! Plenty of bugs, lots of mud, and the beavers keep the water just right.\"", "一只青蛙给她的湿地家园写了评价：\"五颗星！虫子多、泥巴多，河狸还把水位管得刚刚好。\""], "dlg": ["Where do frogs, ducks and beavers all like to live?", "In the wetlands, where there is lots of water.", "On the moon, where there is no air."], "us": "/ˈwɛtˌlænd/"}, "animal": {"zh": "动物", "phrases": [["wild animal", "野生动物"], ["animal kingdom", "动物王国"]], "scene": ["ai", "At the animal talent show, the beaver built a stage in five minutes. The judges gave him a prize before anyone even sang.", "在动物才艺大赛上，河狸五分钟就搭好了舞台。还没有人开始唱歌，评委们就先给他颁了奖。"], "dlg": ["What is your favorite animal?", "I love beavers because they are great builders.", "I am seven years old."], "us": "/ˈænəməl/"}, "branch": {"zh": "树枝；分支", "phrases": [["olive branch", "橄榄枝（和平的象征）"], ["a branch of science", "科学的一个分支"]], "scene": ["ai", "A branch fell into the river and said, \"Oh no, I'm lost!\" A beaver picked it up and said, \"Don't worry, you're part of my new house now.\"", "一根树枝掉进河里：\"糟了，我迷路了！\"河狸把它捡起来说：\"别担心，你现在是我新房子的一部分啦。\""], "dlg": ["What is the beaver carrying in its mouth?", "A long branch for its dam.", "A cup of hot chocolate."], "us": "/bræntʃ/"}, "dam": {"zh": "水坝", "phrases": [["build a dam", "筑坝"], ["the dam broke", "水坝决堤了"]], "scene": ["ai", "The river complained, \"Who put this wall here?\" The beaver replied, \"It's not a wall, it's a dam — now you can be a pond!\"", "小河抱怨道：\"谁在这儿砌了堵墙？\"河狸回答：\"这不是墙，是水坝——现在你可以变成池塘啦！\""], "dlg": ["Why is the water so deep behind those sticks?", "A beaver built a dam to block the stream.", "Because the fish drank all the water."], "us": "/dæm/"}, "keep": {"zh": "保持；留着", "phrases": [["keep calm", "保持冷静"], ["keep in touch", "保持联系"], ["keep an eye on", "留意；照看"]], "scene": ["proverb", "Keep calm and carry on.", "保持冷静，继续前进。", "英国二战宣传海报标语（1939）", "https://en.wikipedia.org/wiki/Keep_Calm_and_Carry_On"], "dlg": ["It's raining and I'm so cold!", "Put on your coat. It will keep you warm.", "Let's eat ice cream outside."], "us": "/kip/"}, "water": {"zh": "水", "phrases": [["a fish out of water", "离开水的鱼；不自在"], ["water under the bridge", "过去的事就让它过去吧"]], "scene": ["song", "Jack and Jill went up the hill / To fetch a pail of water.", "杰克和吉尔爬上山坡，去打一桶水。", "英文童谣《Jack and Jill》（传统儿歌，公有领域）", "https://en.wikipedia.org/wiki/Jack_and_Jill"], "dlg": ["I just ran around the park. I'm so thirsty!", "Here, have a glass of water.", "I like to read books at night."], "us": "/ˈwɔtɚ/"}, "build": {"zh": "建造", "phrases": [["build a house", "盖房子"], ["Rome wasn't built in a day.", "罗马不是一天建成的（冰冻三尺非一日之寒）"]], "scene": ["proverb", "Rome wasn't built in a day.", "罗马不是一天建成的。", "英语谚语（源自中世纪法语谚语）", "https://en.wikipedia.org/wiki/Rome_wasn%27t_built_in_a_day"], "dlg": ["What are you doing with all those blocks?", "I'm going to build a tall tower!", "I'm going to eat them for lunch."], "us": "/bɪld/"}, "chew": {"zh": "咀嚼；啃", "phrases": [["chew gum", "嚼口香糖"], ["bite off more than you can chew", "贪多嚼不烂；揽下做不了的事"]], "scene": ["ai", "A beaver tried chewing gum for the first time. Ten seconds later he said, \"This tree is too small!\"", "一只河狸第一次尝试嚼口香糖。十秒钟后它说：\"这棵树也太小了吧！\""], "dlg": ["Mom, why should I eat slowly?", "So you can chew your food well.", "So the moon can come out."], "us": "/tʃu/"}, "food": {"zh": "食物", "phrases": [["fast food", "快餐"], ["food for thought", "值得思考的东西"]], "scene": ["movie", "Fish are friends, not food.", "鱼是朋友，不是食物。", "电影《海底总动员》Finding Nemo（2003），鲨鱼布鲁斯的口号", "https://en.wikipedia.org/wiki/Finding_Nemo"], "dlg": ["What do beavers eat?", "Their food is bark, leaves and plants.", "They eat pizza and French fries."], "us": "/fud/"}, "fur": {"zh": "皮毛", "phrases": [["fur coat", "皮草大衣"], ["soft fur", "软软的毛"]], "scene": ["ai", "A cat and a beaver argued about whose fur was better. Then it rained. The beaver stayed dry, and the cat decided to stop arguing.", "一只猫和一只河狸争论谁的毛更好。后来下雨了，河狸一点没湿，猫就决定不争了。"], "dlg": ["Why doesn't the beaver get cold in the river?", "Its thick fur keeps it warm and dry.", "Because it wears a raincoat."], "us": "/fɝ/"}, "gnaw": {"zh": "啃；咬", "phrases": [["gnaw on a bone", "啃骨头"], ["gnaw at someone", "（担忧）折磨某人"]], "scene": ["ai", "The tree said, \"Please stop gnawing on me!\" The beaver said, \"Sorry, I just can't stop — my teeth keep growing!\"", "大树说：\"请别再啃我啦！\"河狸说：\"对不起，我停不下来——我的牙一直在长！\""], "dlg": ["What is that beaver doing to the tree?", "It is gnawing the trunk with its sharp teeth.", "It is reading the tree a bedtime story."], "us": "/nɔ/"}, "help": {"zh": "帮助", "phrases": [["help yourself", "请随便用（吃）"], ["give a hand", "帮把手"]], "scene": ["proverb", "God helps those who help themselves.", "天助自助者。", "英语谚语，富兰克林《穷理查年鉴》（1736）使之流行", "https://en.wikipedia.org/wiki/God_helps_those_who_help_themselves"], "dlg": ["This box is too heavy for me!", "Don't worry, I can help you carry it.", "I don't like the color blue."], "us": "/hɛlp/"}, "life": {"zh": "生活；生命", "phrases": [["wildlife", "野生动物"], ["that's life", "这就是生活"]], "scene": ["movie", "My mama always said life was like a box of chocolates. You never know what you're gonna get.", "我妈妈常说，生活就像一盒巧克力，你永远不知道下一块是什么味道。", "电影《阿甘正传》Forrest Gump（1994）", "https://en.wikipedia.org/wiki/Forrest_Gump"], "dlg": ["What is life like for a beaver?", "It is busy! It builds, swims and chews all day.", "It is a red apple on the table."], "us": "/laɪf/"}, "lodge": {"zh": "（河狸的）窝；小屋", "phrases": [["ski lodge", "滑雪小屋"], ["beaver lodge", "河狸窝"]], "scene": ["ai", "A beaver invited a duck to his lodge. \"Where's the front door?\" asked the duck. \"Underwater,\" said the beaver. The duck said, \"I'll wait outside.\"", "河狸请鸭子去它的小窝做客。\"前门在哪儿？\"鸭子问。\"在水下。\"河狸说。鸭子说：\"那我还是在外面等吧。\""], "dlg": ["Where do beavers sleep at night?", "In their lodge, a home made of sticks and mud.", "In a big hotel in the city."], "us": "/lɑdʒ/"}, "nostril": {"zh": "鼻孔", "phrases": [["flare your nostrils", "张大鼻孔"], ["nostrils close", "鼻孔闭合"]], "scene": ["ai", "When the beaver dives, his nostrils close like tiny doors. \"No water allowed!\" he says. \"This nose is private!\"", "河狸潜水时，鼻孔像两扇小门一样关上。\"水不准进来！\"它说，\"这个鼻子是私人领地！\""], "dlg": ["How does a beaver keep water out of its nose?", "It closes its nostrils when it dives.", "It wears big sunglasses."], "us": "/ˈnɑstrɪl/"}, "predator": {"zh": "捕食者", "phrases": [["top predator", "顶级捕食者"], ["predator and prey", "捕食者与猎物"]], "scene": ["ai", "A hungry wolf waited by the beaver lodge all night. In the morning the beaver waved from underwater. The wolf went home for cereal.", "一只饿狼在河狸窝旁守了一整夜。早上，河狸在水下向它挥挥手。狼只好回家吃麦片了。"], "dlg": ["Why do beavers dive when a wolf comes?", "The wolf is a predator, so they hide in the water.", "Because they want to take a bath."], "us": "/ˈprɛdətɚ/"}, "shape": {"zh": "形状；塑造", "phrases": [["in good shape", "身体好；状态好"], ["take shape", "成形"]], "scene": ["ai", "The river asked the beaver, \"What shape should I be today?\" The beaver said, \"Pond-shaped, please!\" and built a dam.", "小河问河狸：\"我今天该是什么形状？\"河狸说：\"请变成池塘形！\"然后就筑起了水坝。"], "dlg": ["What shape is a beaver's tail?", "It is flat, like a paddle.", "It is shaped like a star in the sky."], "us": "/ʃeɪp/"}, "stay": {"zh": "停留；保持", "phrases": [["stay up late", "熬夜"], ["stay safe", "注意安全"]], "scene": ["ai", "\"Stay inside, it's snowing!\" said Mom Beaver. The kits smiled. Their lodge was warm, and they had a pile of sticks to snack on.", "\"待在屋里，外面下雪啦！\"河狸妈妈说。小河狸们都笑了：屋子暖暖的，还有一大堆树枝当零食。"], "dlg": ["It is very cold outside tonight.", "Let's stay home and read a book.", "Let's jump into the cold lake!"], "us": "/steɪ/"}, "tail": {"zh": "尾巴", "phrases": [["wag its tail", "摇尾巴"], ["heads or tails", "（掷硬币）正面还是反面"]], "scene": ["ai", "A dog wagged his tail to say hello. The beaver slapped his tail on the water to say hello. Everybody got wet.", "小狗摇尾巴打招呼。河狸用尾巴拍水打招呼。结果大家都被溅湿了。"], "dlg": ["What does a beaver do with its tail?", "It steers when swimming and slaps the water to warn others.", "It uses its tail to brush its teeth."], "us": "/teɪl/"}, "tasty": {"zh": "美味的", "phrases": [["a tasty snack", "好吃的零食"], ["tasty treat", "美味的小点心"]], "scene": ["ai", "To you, tree bark tastes like cardboard. To a beaver, it's the tastiest cake in the world. Food is all about who is eating it!", "对你来说，树皮像纸板一样难吃；对河狸来说，它是世上最好吃的蛋糕。好不好吃，要看是谁在吃！"], "dlg": ["How is the soup?", "It's really tasty! Can I have some more?", "It's on the second floor."], "us": "/ˈteɪsti/"}, "tree": {"zh": "树", "phrases": [["family tree", "家谱；家族树"], ["can't see the forest for the trees", "只见树木，不见森林"]], "scene": ["poem", "I think that I shall never see / A poem lovely as a tree.", "我想我永远也见不到，一首像树一样美丽的诗。", "Joyce Kilmer 诗歌《Trees》（1913）", "https://en.wikipedia.org/wiki/Trees_(poem)"], "dlg": ["Where does the bird live?", "It lives in a nest at the top of the tree.", "It lives inside the fridge."], "us": "/tri/"}, "underwater": {"zh": "在水下", "phrases": [["underwater world", "水下世界"], ["hold your breath underwater", "在水下屏住呼吸"]], "scene": ["ai", "A beaver can stay underwater for 15 minutes. His friend the fish said, \"That's cute. I've been under here my whole life.\"", "河狸能在水下待15分钟。它的鱼朋友说：\"挺可爱的。我可是一辈子都在水下呢。\""], "dlg": ["How long can a beaver stay underwater?", "About fifteen minutes without breathing!", "About fifteen birthday cakes."], "us": "/ˈʌndɚˌwɔtɚ/"}, "warm": {"zh": "温暖的", "phrases": [["warm-hearted", "热心肠的"], ["keep warm", "保暖"]], "scene": ["ai", "On the coldest night, the beaver family slept in one big furry pile. \"Who needs a heater,\" said Dad, \"when you have a family?\"", "在最冷的夜里，河狸一家挤成一大团毛茸茸地睡觉。爸爸说：\"有家人在，谁还需要暖气呢？\""], "dlg": ["Brr, my hands are freezing!", "Here, wear my gloves. They will keep your hands warm.", "I think the sun is a big banana."], "us": "/wɔrm/"}, "waterproof": {"zh": "防水的", "phrases": [["waterproof jacket", "防水夹克"], ["waterproof watch", "防水手表"]], "scene": ["ai", "A beaver walked into a shop and asked for a raincoat. The shopkeeper laughed: \"Sir, your fur is already waterproof!\"", "一只河狸走进商店要买雨衣。店主笑了：\"先生，您的毛本来就是防水的！\""], "dlg": ["Will my new jacket get wet in the rain?", "No, it's waterproof, just like beaver fur.", "Yes, it is made of paper towels."], "us": "/ˈwɔtɚˌpruf/"}, "adapt": {"zh": "适应", "phrases": [["adapt to change", "适应变化"], ["adapt quickly", "快速适应"]], "scene": ["ai", "A penguin moved to the desert. \"I'll adapt!\" he said, and put on sunscreen. Two hours later he moved back to the ice.", "一只企鹅搬到了沙漠。\"我能适应！\"他说着涂上了防晒霜。两个小时后，他又搬回了冰面。"], "dlg": ["How do beavers live so well in water?", "Their bodies have adapted: webbed feet, a flat tail and oily fur.", "They bought a swimming pool."], "us": "/əˈdæpt/"}, "bark": {"zh": "树皮；（狗）叫", "phrases": [["his bark is worse than his bite", "刀子嘴豆腐心"], ["barking up the wrong tree", "找错了对象；搞错了方向"]], "scene": ["proverb", "His bark is worse than his bite.", "他只是嘴上凶，其实不坏（刀子嘴豆腐心）。", "英语俗语", ""], "dlg": ["What is the beaver eating?", "It is eating the bark from a birch tree.", "It is eating a big hamburger."], "us": "/bɑrk/"}, "block": {"zh": "阻挡；块", "phrases": [["building blocks", "积木；基础"], ["around the block", "在街区附近转一圈"]], "scene": ["ai", "The beaver blocked the stream. The stream blocked the road. The road blocked the mail truck. Now the beaver gets his letters by duck.", "河狸挡住了小溪，小溪挡住了马路，马路挡住了邮车。现在河狸只能靠鸭子送信啦。"], "dlg": ["Why did the stream become a pond?", "Beavers blocked it with a dam.", "It turned into a cupcake."], "us": "/blɑk/"}, "colony": {"zh": "群落；一大家子", "phrases": [["ant colony", "蚁群"], ["a colony of beavers", "一窝河狸"]], "scene": ["ai", "In the beaver colony, everyone has a job: Dad fixes the dam, Mom fixes the lodge, and the kits fix... their snacks.", "在河狸群里，每个成员都有工作：爸爸修坝，妈妈修房子，小河狸们负责……修理零食。"], "dlg": ["How many beavers live together?", "A colony is a family of about four to eight beavers.", "Only one, and it lives on a bus."], "us": "/ˈkɑləni/"}, "dry": {"zh": "干的；弄干", "phrases": [["high and dry", "孤立无援"], ["dry your hands", "把手擦干"]], "scene": ["ai", "After a swim, the beaver shakes himself dry. Everyone nearby suddenly needs a towel.", "游完泳，河狸一甩身子就干了。旁边的大家突然都需要毛巾了。"], "dlg": ["My shoes are all wet!", "Put them in the sun and they will be dry soon.", "Let's put them in the bath."], "us": "/draɪ/"}, "home": {"zh": "家", "phrases": [["home sweet home", "家，甜蜜的家"], ["make yourself at home", "别客气，就像在自己家一样"]], "scene": ["movie", "There's no place like home.", "哪里都比不上家。", "电影《绿野仙踪》The Wizard of Oz（1939），多萝西", "https://en.wikipedia.org/wiki/The_Wizard_of_Oz_(1939_film)"], "dlg": ["It's getting dark. Where are you going?", "I'm going home for dinner.", "I'm going to the moon on my bike."], "us": "/hoʊm/"}, "layer": {"zh": "层", "phrases": [["layer cake", "千层蛋糕"], ["the ozone layer", "臭氧层"]], "scene": ["ai", "Onions have layers. Cakes have layers. Beavers have layers too: a fluffy undercoat, long outer fur, and a layer of fat. Beavers are basically cakes that swim.", "洋葱有层，蛋糕有层，河狸也有层：蓬松的底绒、长长的外毛，还有一层脂肪。河狸简直就是会游泳的蛋糕。"], "dlg": ["It's snowing. What should I wear?", "Wear a few warm layers, like a sweater under your coat.", "Wear your swimsuit only."], "us": "/ˈleɪɚ/"}, "learn": {"zh": "学习", "phrases": [["learn by heart", "背下来"], ["live and learn", "活到老学到老"]], "scene": ["ai", "A little beaver asked, \"How did you learn to build dams?\" Grandpa said, \"I made a hundred leaky ones first.\" Learning is just mistakes that keep trying.", "小河狸问：\"你是怎么学会筑坝的？\"爷爷说：\"我先做了一百个漏水的。\"学习，就是不停尝试的错误。"], "dlg": ["Why do you read so many books about animals?", "Because I want to learn new things!", "Because books are good to eat."], "us": "/lɝn/"}, "mud": {"zh": "泥", "phrases": [["muddy", "泥泞的"], ["clear as mud", "一点也不清楚（反话）"]], "scene": ["ai", "Kids get in trouble for playing in mud. Beavers get praised for it: \"Great mud on the lodge today, son!\"", "小孩玩泥巴会挨骂，河狸玩泥巴却会被夸：\"儿子，今天房子上的泥糊得真棒！\""], "dlg": ["Why are your boots so dirty?", "I walked through the mud by the river.", "I washed them in milk."], "us": "/mʌd/"}, "safe": {"zh": "安全的", "phrases": [["safe and sound", "平安无事"], ["better safe than sorry", "小心驶得万年船"]], "scene": ["proverb", "Better safe than sorry.", "宁可安全，不要后悔（小心为上）。", "英语谚语", ""], "dlg": ["Is it okay to cross the street now?", "Wait for the green light, then it's safe.", "Yes, close your eyes and run!"], "us": "/seɪf/"}, "scent": {"zh": "气味", "phrases": [["on the scent", "发现线索"], ["a sweet scent", "香甜的气味"]], "scene": ["ai", "Beavers leave scent mounds like sticky notes: \"This pond is taken. Thanks, The Beavers.\"", "河狸会留下气味堆，就像便利贴一样：\"本池塘已有主人。谢谢，河狸一家敬上。\""], "dlg": ["How does a beaver tell others \"This is my home\"?", "It leaves its scent on little piles of mud.", "It sends them an email."], "us": "/sɛnt/"}, "sharp": {"zh": "锋利的", "phrases": [["sharp as a tack", "非常聪明"], ["look sharp", "打起精神；快点"]], "scene": ["ai", "The beaver never sharpens his teeth. Chewing trees does it for him. \"It's a self-sharpening system,\" he brags.", "河狸从来不用磨牙，啃树就帮它磨好了。\"这是自动磨刀系统。\"它得意地说。"], "dlg": ["Be careful with that knife!", "I know, it's very sharp.", "I know, it's very sleepy."], "us": "/ʃɑrp/"}, "soft": {"zh": "柔软的", "phrases": [["soft drink", "软饮料；汽水"], ["have a soft spot for", "对……情有独钟"]], "scene": ["ai", "Beaver babies sleep on soft wood shavings. \"Better than any pillow,\" says Mom. The kits agree, then chew the pillow.", "小河狸睡在软软的木屑上。\"比什么枕头都好。\"妈妈说。小河狸们点头同意，然后把枕头吃了。"], "dlg": ["Which blanket do you want?", "The soft one, please. It feels like a cloud.", "The one made of rocks."], "us": "/sɑft/"}, "stream": {"zh": "小溪", "phrases": [["upstream and downstream", "上游和下游"], ["stream of consciousness", "意识流"]], "scene": ["song", "Row, row, row your boat, / Gently down the stream.", "划呀划呀划小船，轻轻顺着小溪漂。", "英文童谣《Row, Row, Row Your Boat》（传统儿歌，公有领域）", "https://en.wikipedia.org/wiki/Row,_Row,_Row_Your_Boat"], "dlg": ["Where can we find fish near here?", "In the little stream behind the hill.", "In my pencil box."], "us": "/strim/"}, "strong": {"zh": "强壮的", "phrases": [["strong as an ox", "力大如牛"], ["going strong", "依然很好；势头强劲"]], "scene": ["ai", "An ant said, \"I can lift fifty times my weight.\" The beaver said, \"I can cut down a tree with my teeth.\" The tree said, \"Can we talk about something else?\"", "蚂蚁说：\"我能举起自己体重五十倍的东西。\"河狸说：\"我能用牙咬断一棵树。\"树说：\"咱们能换个话题吗？\""], "dlg": ["How can a beaver cut down a tree?", "Its jaws and teeth are very strong.", "It asks the tree nicely to fall."], "us": "/strɔŋ/"}, "twig": {"zh": "细树枝", "phrases": [["snap a twig", "折断细枝"], ["twigs and leaves", "枝叶"]], "scene": ["ai", "A bird and a beaver both collected twigs. The bird built a nest the size of a hat. The beaver built a house the size of a car. They agreed to stop comparing.", "小鸟和河狸都在捡树枝。小鸟搭了个帽子大的窝，河狸盖了个汽车大的房子。它们决定以后不再互相比了。"], "dlg": ["What is the bird carrying?", "A little twig for its nest.", "A heavy piano."], "us": "/twɪɡ/"}, "webbed": {"zh": "有蹼的", "phrases": [["webbed feet", "有蹼的脚"], ["web", "网；蹼"]], "scene": ["ai", "Ducks and beavers both have webbed feet. They meet every Sunday for a swimming race. It always ends in a tie, and a picnic.", "鸭子和河狸都有带蹼的脚。它们每个星期天比赛游泳，结果总是平局——然后一起野餐。"], "dlg": ["Why are ducks such good swimmers?", "They have webbed feet that push the water like paddles.", "They have wheels on their feet."], "us": "/wɛbd/"}, "busy": {"zh": "忙碌的", "phrases": [["busy as a bee", "像蜜蜂一样忙"], ["keep busy", "让自己忙起来"]], "scene": ["ai", "\"Are you busy?\" asked the owl at midnight. \"Always,\" said the beaver, holding three sticks. \"Beavers don't do weekends.\"", "\"你忙吗？\"猫头鹰半夜问。\"一直都忙。\"河狸抱着三根树枝说，\"河狸没有周末。\""], "dlg": ["Can you play with me now?", "Sorry, I'm busy with my homework. Maybe later!", "Sorry, I am a banana."], "us": "/ˈbɪzi/"}, "carry": {"zh": "携带；搬运", "phrases": [["carry on", "继续"], ["carry out", "执行；完成"]], "scene": ["ai", "A beaver carried a branch longer than his whole body across the pond. A turtle watched and said, \"Show-off.\"", "河狸叼着一根比自己身子还长的树枝游过池塘。一只乌龟看着说：\"爱显摆。\""], "dlg": ["These bags are heavy!", "Let me carry one for you.", "Let me sing a song to the bags."], "us": "/ˈkæri/"}, "danger": {"zh": "危险", "phrases": [["in danger", "处于危险中"], ["out of danger", "脱离危险"]], "scene": ["ai", "When a beaver senses danger, it slaps its tail — SPLASH! — and every beaver dives. It is the loudest \"Watch out!\" in the forest.", "河狸察觉到危险时会用尾巴拍水——啪！——所有河狸立刻潜水。这是森林里最响亮的\"小心！\""], "dlg": ["Why did all the beavers suddenly dive?", "One beaver slapped its tail to warn of danger.", "They wanted to look for treasure."], "us": "/ˈdeɪndʒɚ/"}, "dig": {"zh": "挖", "phrases": [["dig in", "开吃吧；开始干"], ["dig deep", "深入挖掘；拿出全力"]], "scene": ["ai", "A dog dug a hole to hide a bone. A beaver dug a canal to move a tree. The dog decided he needed a bigger dream.", "小狗挖洞藏骨头，河狸挖水渠运大树。小狗觉得自己需要一个更大的梦想。"], "dlg": ["What are you doing in the garden?", "I'm digging a hole to plant a tree.", "I'm flying a kite under the bed."], "us": "/dɪɡ/"}, "dive": {"zh": "潜水；跳水", "phrases": [["dive in", "一头扎进去；开始做"], ["scuba diving", "水肺潜水"]], "scene": ["ai", "The beaver dove into the pond to fetch dinner. He came up with a stick, a leaf, and a very surprised fish.", "河狸潜进池塘去拿晚饭，浮上来时叼着一根树枝、一片叶子，还有一条非常惊讶的鱼。"], "dlg": ["How does a beaver get into its lodge?", "It dives underwater and swims through the door.", "It rings the doorbell."], "us": "/daɪv/"}, "family": {"zh": "家庭", "phrases": [["family tree", "家谱"], ["run in the family", "家族遗传"]], "scene": ["ai", "In a beaver family, the older kids help babysit the new babies. Big brother beaver says it's the hardest job on the pond.", "在河狸家庭里，大孩子会帮忙照顾刚出生的小宝宝。河狸大哥说，这是池塘里最难的工作。"], "dlg": ["Who lives in your house?", "My family: Mom, Dad, my sister and me.", "A dinosaur and a robot."], "us": "/ˈfæməli/"}, "fast": {"zh": "快的", "phrases": [["fast food", "快餐"], ["fast asleep", "睡得很熟"]], "scene": ["proverb", "Slow and steady wins the race.", "慢而稳者胜（龟兔赛跑的寓意）。", "《伊索寓言·龟兔赛跑》（公有领域）", "https://en.wikipedia.org/wiki/The_Tortoise_and_the_Hare"], "dlg": ["Wow, how did you finish so quickly?", "I'm a fast reader!", "I'm a blue umbrella."], "us": "/fæst/"}, "fat": {"zh": "脂肪；胖的", "phrases": [["chew the fat", "闲聊"], ["low-fat milk", "低脂牛奶"]], "scene": ["ai", "Beavers eat lots of food in fall to store fat. Then in winter they say, \"Not chubby. Insulated.\"", "河狸秋天会多吃东西储存脂肪。到了冬天它们会说：\"这不叫胖，这叫保温层。\""], "dlg": ["How do beavers stay warm in winter water?", "A layer of fat under the skin keeps them warm.", "They drink hot tea all day."], "us": "/fæt/"}, "flood": {"zh": "洪水；淹没", "phrases": [["flood of tears", "泪如泉涌"], ["flash flood", "山洪"]], "scene": ["ai", "The beaver built a dam and flooded the valley. The ducks threw him a party. The mice moved upstairs.", "河狸筑坝淹了山谷。鸭子们为他开了派对，老鼠们搬到了楼上。"], "dlg": ["Why is the field full of water?", "The river flooded after the big rain.", "Because the cows filled it with milk."], "us": "/flʌd/"}, "foot": {"zh": "脚（复数 feet）", "phrases": [["on foot", "步行"], ["put your foot down", "坚决反对"]], "scene": ["ai", "A beaver's back feet are big and webbed for swimming. His front feet are small and clever, like hands. \"Two pairs of tools,\" he says.", "河狸的后脚又大又有蹼，用来游泳；前脚小巧灵活，像手一样。\"两套工具。\"它说。"], "dlg": ["Did you take the bus to school?", "No, I came on foot. It's not far.", "No, I came on a whale."], "us": "/fʊt/"}, "rodent": {"zh": "啮齿动物", "phrases": [["rodent family", "啮齿动物家族"], ["like a rodent", "像啮齿动物一样"]], "scene": ["ai", "At the rodent family reunion, the mouse was the smallest and the beaver was the biggest. They all had the same big front teeth in the photo.", "在啮齿动物家族聚会上，老鼠最小，河狸最大。合影里，大家都露着一样的大门牙。"], "dlg": ["Is a beaver a kind of fish?", "No, it's a rodent, like a mouse or a squirrel.", "Yes, it's a kind of cake."], "us": "/ˈroʊdənt/"}, "swim": {"zh": "游泳", "phrases": [["sink or swim", "自生自灭；成败全靠自己"], ["go swimming", "去游泳"]], "scene": ["movie", "Just keep swimming.", "只要继续游下去。", "电影《海底总动员》Finding Nemo（2003），多莉", "https://en.wikipedia.org/wiki/Finding_Nemo"], "dlg": ["Can you swim?", "Yes, I learned to swim last summer.", "Yes, I learned to fly last night."], "us": "/swɪm/"}, "eyelid": {"zh": "眼睑；眼皮", "phrases": [["without batting an eyelid", "眼都不眨一下；镇定自若"], ["heavy eyelids", "眼皮发沉（很困）"]], "scene": ["ai", "Beavers have see-through eyelids, like built-in swimming goggles. Kids at the pool wish they had them too.", "河狸有透明的眼睑，就像自带的游泳镜。游泳池里的小朋友们都很羡慕。"], "dlg": ["How can beavers see underwater?", "Clear eyelids cover their eyes like goggles.", "They turn on a flashlight."], "us": "/ˈaɪˌlɪd/"}, "ear": {"zh": "耳朵", "phrases": [["all ears", "洗耳恭听"], ["play it by ear", "见机行事"]], "scene": ["song", "Eyes and ears and mouth and nose.", "眼睛、耳朵、嘴巴和鼻子。", "英文儿歌《Head, Shoulders, Knees and Toes》（传统儿歌）", "https://en.wikipedia.org/wiki/Head,_Shoulders,_Knees_and_Toes"], "dlg": ["I have a secret to tell you!", "I'm all ears!", "I'm all shoes!"], "us": "/ir/"}, "paddle": {"zh": "船桨；划桨", "phrases": [["paddle your own canoe", "自力更生"], ["paddle board", "桨板"]], "scene": ["ai", "A beaver's tail looks like a paddle. A kayaker once asked to borrow it. The beaver said, \"Sorry, it's attached.\"", "河狸的尾巴像船桨。有个划皮艇的人想借它用。河狸说：\"不好意思，它是长在我身上的。\""], "dlg": ["How do we make the canoe go?", "We push the water with our paddles.", "We sing to the canoe."], "us": "/ˈpædəl/"}, "close": {"zh": "关闭；接近", "phrases": [["close call", "好险；侥幸脱险"], ["close to", "靠近"]], "scene": ["ai", "The beaver closed his ears, closed his nose, closed his lips, and dove. \"Shop closed,\" said the sign on his back.", "河狸关上耳朵、关上鼻孔、闭上嘴唇，一头潜下水。背上的牌子写着：\"暂停营业。\""], "dlg": ["It's windy and the papers are flying!", "Please close the window.", "Please open the fridge."], "us": "/kloʊs/"}, "extra": {"zh": "额外的", "phrases": [["go the extra mile", "多付出一些努力"], ["extra time", "加时赛"]], "scene": ["ai", "The beaver always builds his dam a little extra tall. \"Just in case,\" he says. Then the big rain comes, and everyone says thank you.", "河狸总把水坝修得高一点点。\"以防万一。\"它说。后来大雨来了，大家都来道谢。"], "dlg": ["Do you have a pencil I can use?", "Yes, I have an extra one. Here you go!", "Yes, I have an extra elephant."], "us": "/ˈɛkstrə/"}, "brain": {"zh": "大脑", "phrases": [["use your brain", "动动脑筋"], ["brainstorm", "头脑风暴"], ["no-brainer", "不用想的简单事"]], "scene": ["ai", "Your brain weighs about as much as a big bag of sugar, but it uses about one-fifth of your energy. It's the hungriest thing you own!", "你的大脑大约和一大袋糖一样重，却要用掉你大约五分之一的能量。它是你身上最\"能吃\"的东西！"], "dlg": ["This puzzle is so hard!", "Let's use our brains and try again.", "Let's use our shoes and eat it."], "us": "/breɪn/"}, "neuron": {"zh": "神经元", "phrases": [["neurons fire", "神经元放电（被激活）"], ["a network of neurons", "神经元网络"]], "scene": ["ai", "Two neurons met at a synapse. \"Got any news?\" asked one. \"Yes! The kid just saw a puppy!\" They passed the message on in less than a blink.", "两个神经元在突触相遇。\"有新消息吗？\"一个问。\"有！小朋友刚看到一只小狗！\"它们眨眼之间就把消息传了出去。"], "dlg": ["What carries messages around your brain?", "Tiny cells called neurons.", "Little mail trucks with wheels."], "us": "/ˈnʊrɑn/"}, "signal": {"zh": "信号", "phrases": [["send a signal", "发信号"], ["traffic signal", "交通信号灯"]], "scene": ["ai", "When you touch something hot, a signal races to your spinal cord and back — your hand jumps away before you even think \"Ouch!\"", "当你碰到烫的东西，信号会飞快地传到脊髓再传回来——你还没想\"好烫！\"手就已经缩回来了。"], "dlg": ["How do you know when to stop at the street?", "The red signal tells us to stop.", "The ice cream tells us to stop."], "us": "/ˈsɪɡnəl/"}, "memory": {"zh": "记忆", "phrases": [["from memory", "凭记忆"], ["a memory like an elephant", "记性特别好"]], "scene": ["book", "It's no use going back to yesterday, because I was a different person then.", "回到昨天是没有用的，因为那时我是另一个人了。", "Lewis Carroll《爱丽丝梦游仙境》Alice's Adventures in Wonderland（1865）第10章", "https://www.gutenberg.org/ebooks/11"], "dlg": ["Do you remember your first day of school?", "Yes! It's one of my happiest memories.", "Yes! It's a green vegetable."], "us": "/ˈmɛmɚi/"}, "cell": {"zh": "细胞", "phrases": [["brain cell", "脑细胞"], ["cell phone", "手机"]], "scene": ["ai", "You are made of about 30 trillion cells. If each cell said \"hi\" once a second, it would take about a million years to hear them all!", "你的身体由大约30万亿个细胞组成。如果每个细胞每秒说一声\"嗨\"，要听完它们得花大约一百万年！"], "dlg": ["What is the smallest living part of your body?", "A cell. You have trillions of them!", "A shoe. You have two of them!"], "us": "/sɛl/"}, "body": {"zh": "身体", "phrases": [["body language", "肢体语言"], ["mind and body", "身心"]], "scene": ["ai", "Your body is like a busy city: blood is the delivery trucks, nerves are the phone lines, and the brain is the mayor who never sleeps.", "你的身体像一座繁忙的城市：血液是送货车，神经是电话线，大脑是从不睡觉的市长。"], "dlg": ["Why do we need to exercise?", "To keep our bodies strong and healthy.", "To make the clouds turn pink."], "us": "/ˈbɑdi/"}, "think": {"zh": "想；思考", "phrases": [["think outside the box", "跳出框框思考"], ["think twice", "三思而行"]], "scene": ["book", "I think, therefore I am.", "我思故我在。", "笛卡尔 René Descartes《方法论》（1637）", "https://en.wikipedia.org/wiki/Cogito,_ergo_sum"], "dlg": ["What do you think about this drawing?", "I think it's beautiful!", "I think it's Tuesday soup."], "us": "/θɪŋk/"}, "information": {"zh": "信息", "phrases": [["for your information", "供你参考"], ["information age", "信息时代"]], "scene": ["ai", "Every second your senses send your brain millions of bits of information. Your brain politely ignores most of it — like the feeling of your socks right now. (You noticed now, didn't you?)", "你的感官每秒都给大脑送去海量信息。大脑会礼貌地忽略大部分——比如此刻袜子穿在脚上的感觉。（你现在注意到了吧？）"], "dlg": ["Where can I find information about dinosaurs?", "Try the library or a good science book.", "Try the washing machine."], "us": "/ˌɪnfɚˈmeɪʃən/"}, "message": {"zh": "消息；信息", "phrases": [["leave a message", "留言"], ["get the message", "明白了意思"]], "scene": ["ai", "Your brain sends messages faster than a text: some nerve signals travel over 100 meters per second — faster than a race car!", "大脑发消息比手机短信还快：有些神经信号每秒能跑100多米——比赛车还快！"], "dlg": ["Grandma called when you were out.", "Did she leave a message?", "Did she leave a dinosaur?"], "us": "/ˈmɛsədʒ/"}, "control": {"zh": "控制", "phrases": [["under control", "在控制之中"], ["remote control", "遥控器"]], "scene": ["ai", "The brain is the remote control for your body — except you can't lose it in the sofa.", "大脑是你身体的遥控器——只不过它不会掉进沙发缝里找不到。"], "dlg": ["Which part of you controls your hands?", "My brain sends signals to my muscles.", "My hat tells my hands what to do."], "us": "/kənˈtroʊl/"}, "move": {"zh": "移动；动", "phrases": [["move on", "继续前进；放下过去"], ["get a move on", "快点"]], "scene": ["ai", "To take one step, your brain moves about 200 muscles. And you do it while thinking about lunch!", "迈出一步，大脑要指挥大约200块肌肉一起动。而你一边走，还一边在想午饭吃什么！"], "dlg": ["Can you help me move this chair?", "Sure, you lift that side and I'll lift this side.", "Sure, I'll paint it purple."], "us": "/muv/"}, "sound": {"zh": "声音", "phrases": [["sound asleep", "睡得很沉"], ["safe and sound", "安然无恙"]], "scene": ["movie", "The hills are alive with the sound of music.", "群山因音乐之声而充满生机。", "电影《音乐之声》The Sound of Music（1965）主题曲", "https://en.wikipedia.org/wiki/The_Sound_of_Music_(film)"], "dlg": ["What is that sound outside?", "It's just the wind blowing through the trees.", "It's a sandwich."], "us": "/saʊnd/"}, "grow": {"zh": "生长；长大", "phrases": [["grow up", "长大"], ["money doesn't grow on trees", "钱不是树上长出来的（要珍惜）"]], "scene": ["book", "All children, except one, grow up.", "所有的孩子都会长大，只有一个例外。", "J. M. Barrie《彼得·潘》Peter and Wendy（1911）第一句", "https://www.gutenberg.org/ebooks/16"], "dlg": ["What do you want to be when you grow up?", "I want to be a scientist who studies the brain!", "I want to be yesterday."], "us": "/ɡroʊ/"}, "send": {"zh": "发送", "phrases": [["send off", "送行"], ["send a letter", "寄信"]], "scene": ["ai", "Your eyes send pictures to the back of your brain, upside down! Your brain flips them so you don't walk on the ceiling.", "眼睛把画面送到大脑后部时是倒着的！大脑把它翻过来，你才不会以为自己在天花板上走路。"], "dlg": ["It's Grandpa's birthday tomorrow.", "Let's send him a card today!", "Let's send him to the moon."], "us": "/sɛnd/"}, "chemical": {"zh": "化学物质；化学的", "phrases": [["chemical reaction", "化学反应"], ["chemical messenger", "化学信使"]], "scene": ["ai", "When you laugh with friends, your brain releases happy chemicals. That's why giggles are contagious — your friends' brains want some too!", "和朋友一起大笑时，大脑会释放让人开心的化学物质。所以笑是会传染的——朋友的大脑也想要一点！"], "dlg": ["Why do we wear gloves in the science lab?", "To keep chemicals off our hands.", "To keep our hands from flying away."], "us": "/ˈkɛməkəl/"}, "muscle": {"zh": "肌肉", "phrases": [["flex your muscles", "秀肌肉；显示实力"], ["muscle memory", "肌肉记忆"]], "scene": ["ai", "Your heart is a muscle that never takes a vacation. It beats about 100,000 times a day — and never asks for a day off.", "心脏是一块从不休假的肌肉，一天大约跳10万次——从来不请假。"], "dlg": ["Why are your legs tired?", "I ran a lot today. My muscles need a rest.", "I ate too many clouds."], "us": "/ˈmʌsəl/"}, "feel": {"zh": "感觉", "phrases": [["feel at home", "感觉像在家一样自在"], ["feel like", "想要（做某事）"]], "scene": ["ai", "Your skin can feel a tiny ant walking on it. But you can't feel the Earth spinning at about 1,600 kilometers per hour at the equator. Brains are picky!", "你的皮肤能感觉到一只小蚂蚁在爬，却感觉不到地球在赤道处以每小时约1600公里的速度旋转。大脑可挑剔了！"], "dlg": ["How do you feel today?", "I feel great, thank you!", "I feel like a purple Tuesday."], "us": "/fil/"}, "change": {"zh": "改变", "phrases": [["change your mind", "改变主意"], ["a change of heart", "回心转意"]], "scene": ["ai", "Every time you learn something new, your brain physically changes — new connections grow between neurons. Reading this sentence is changing your brain right now!", "每次学到新东西，大脑都会真的发生改变——神经元之间会长出新的连接。读这句话的时候，你的大脑正在改变！"], "dlg": ["I don't want ice cream anymore. Can I have fruit?", "Sure, you can change your mind.", "Sure, the fruit can drive a car."], "us": "/tʃeɪndʒ/"}, "light": {"zh": "光；轻的", "phrases": [["light as a feather", "轻如鸿毛"], ["see the light", "恍然大悟"]], "scene": ["book", "And God said, Let there be light: and there was light.", "神说，要有光，就有了光。", "《圣经·创世记》1:3（钦定本，公有领域）", "https://en.wikipedia.org/wiki/Let_there_be_light"], "dlg": ["It's too dark to read in here.", "Let me turn on the light.", "Let me turn on the banana."], "us": "/laɪt/"}, "sense": {"zh": "感觉；感官", "phrases": [["common sense", "常识"], ["make sense", "讲得通"]], "scene": ["ai", "People say we have five senses, but scientists count more — like balance, and knowing where your hand is with your eyes closed. Try touching your nose with your eyes shut!", "人们常说我们有五种感官，但科学家数出了更多——比如平衡感，还有闭着眼睛也知道手在哪儿的感觉。闭上眼睛摸摸你的鼻子试试！"], "dlg": ["Why can dogs find lost things so well?", "They have a great sense of smell.", "They have a great sense of pizza."], "us": "/sɛns/"}, "touch": {"zh": "触摸；触觉", "phrases": [["keep in touch", "保持联系"], ["a touch of", "一点点"]], "scene": ["ai", "Your fingertips have so many touch sensors that you can feel a bump smaller than a hair. That's how some people read with their fingers, using Braille.", "指尖的触觉感受器多到能摸出比头发丝还细的凸起。所以有人能用手指读盲文。"], "dlg": ["Can I touch the baby rabbit?", "Yes, but touch it gently.", "Yes, but touch it with a hammer."], "us": "/tʌtʃ/"}, "smell": {"zh": "闻；气味", "phrases": [["smell a rat", "觉得可疑"], ["smell good", "闻起来很香"]], "scene": ["ai", "A smell can bring back a memory instantly. One sniff of cookies and suddenly you're five years old in Grandma's kitchen.", "一种气味能瞬间唤起回忆。闻一下饼干香，你仿佛立刻回到五岁时外婆的厨房。"], "dlg": ["Mmm, what's that smell?", "Mom is baking bread!", "It's the color green."], "us": "/smɛl/"}, "baby": {"zh": "婴儿", "phrases": [["baby steps", "一小步一小步来"], ["cry like a baby", "哭得像个孩子"]], "scene": ["ai", "A newborn baby can't see very far, but it already knows its mom's voice — it heard it for months before being born!", "新生宝宝看不远，却已经认得妈妈的声音——在出生前的好几个月里就一直听着呢！"], "dlg": ["Why is the baby crying?", "Maybe she's hungry or sleepy.", "Maybe she wants to drive the bus."], "us": "/ˈbeɪbi/"}, "know": {"zh": "知道", "phrases": [["know by heart", "熟记"], ["you never know", "谁知道呢；世事难料"]], "scene": ["ai", "The more you know, the more you realize you don't know. Scientists say that's the best part: there's always something new to discover!", "知道得越多，越会发现自己不知道的更多。科学家说这才是最棒的：总有新东西等你去发现！"], "dlg": ["Do you know where my book is?", "Yes, it's on the table by the window.", "Yes, it's a happy giraffe."], "us": "/noʊ/"}, "travel": {"zh": "旅行；传播", "phrases": [["travel light", "轻装出行"], ["time travel", "时间旅行"]], "scene": ["ai", "Light travels about 300,000 kilometers per second. Your nerve signals are much slower — but still fast enough to catch a ball!", "光每秒大约传播30万公里。你的神经信号慢得多——不过接住一个球还是够快的！"], "dlg": ["Where did you travel this summer?", "We traveled to the beach by train.", "We traveled into my sandwich."], "us": "/ˈtrævəl/"}, "connect": {"zh": "连接", "phrases": [["connect the dots", "把线索串起来"], ["stay connected", "保持联系"]], "scene": ["ai", "Each neuron can connect to thousands of others. Your brain has more connections than there are stars in our galaxy!", "每个神经元都能和成千上万个别的神经元相连。你大脑里的连接比银河系里的星星还多！"], "dlg": ["The tablet has no internet!", "Let's connect it to the Wi-Fi.", "Let's connect it to a cat."], "us": "/kəˈnɛkt/"}, "emotion": {"zh": "情绪；情感", "phrases": [["mixed emotions", "百感交集"], ["show emotion", "流露情感"]], "scene": ["ai", "Inside your brain, a small part called the amygdala acts like a smoke alarm for feelings. Sometimes it beeps at spiders, sometimes at math tests.", "大脑里有个叫杏仁核的小部位，像是情绪的烟雾报警器。有时为蜘蛛响，有时为数学考试响。"], "dlg": ["You look a little sad today.", "Yes, but talking about my emotions helps me feel better.", "Yes, I am a tall lamp."], "us": "/ɪˈmoʊʃən/"}, "eye": {"zh": "眼睛", "phrases": [["keep an eye on", "照看"], ["the apple of my eye", "掌上明珠"]], "scene": ["proverb", "Beauty is in the eye of the beholder.", "情人眼里出西施（美在观者眼中）。", "英语谚语", ""], "dlg": ["Something is in my eye!", "Don't rub it. Let's wash it with water.", "Let's put more sand in it."], "us": "/aɪ/"}, "hear": {"zh": "听见", "phrases": [["hear from", "收到……的消息"], ["I can't hear myself think", "吵得没法思考"]], "scene": ["ai", "You hear with your ears, but you listen with your brain. That's why you can hear your name across a noisy room!", "你用耳朵听见，用大脑聆听。所以在吵闹的屋子里，你也能一下听见有人叫你的名字！"], "dlg": ["Did you hear that noise?", "Yes! I think it was thunder.", "Yes! I think it was a sandwich."], "us": "/hir/"}, "important": {"zh": "重要的", "phrases": [["most important", "最重要的"], ["important to me", "对我很重要"]], "scene": ["ai", "Sleep is so important that your brain cleans itself while you sleep, washing away the waste of the day like a night-shift janitor.", "睡眠非常重要，大脑会在你睡觉时清洁自己，像夜班清洁工一样把一天的\"垃圾\"冲走。"], "dlg": ["Why should I eat breakfast?", "It's important. It gives your brain energy for school.", "It's important. Breakfast can fly."], "us": "/ˌɪmˈpɔrtənt/"}, "problem": {"zh": "问题", "phrases": [["no problem", "没问题"], ["problem solving", "解决问题"]], "scene": ["movie", "Houston, we have a problem.", "休斯敦，我们遇到了一个问题。", "电影《阿波罗13号》Apollo 13（1995）", "https://en.wikipedia.org/wiki/Apollo_13_(film)"], "dlg": ["Thank you for helping me!", "No problem! I'm happy to help.", "No problem! The fish is blue."], "us": "/ˈprɑbləm/"}, "scientist": {"zh": "科学家", "phrases": [["rocket scientist", "火箭科学家；（喻）特别聪明的人"], ["young scientist", "小科学家"]], "scene": ["ai", "A scientist is just a grown-up who never stopped asking \"Why?\" Keep asking, and you're already one!", "科学家就是一直没停止问\"为什么\"的大人。只要你不停地问，你已经是一名科学家了！"], "dlg": ["Who studies how the brain works?", "Brain scientists, called neuroscientists.", "Bakers who make bread."], "us": "/ˈsaɪəntɪst/"}, "sleep": {"zh": "睡觉", "phrases": [["sleep on it", "考虑一晚再决定"], ["sleep like a log", "睡得很沉"]], "scene": ["proverb", "Early to bed and early to rise, makes a man healthy, wealthy, and wise.", "早睡早起，使人健康、富有又聪明。", "本杰明·富兰克林《穷理查年鉴》Poor Richard's Almanack（1735）", "https://en.wikipedia.org/wiki/Poor_Richard%27s_Almanack"], "dlg": ["I'm so tired, I can't keep my eyes open.", "You should go to sleep early tonight.", "You should eat a pillow."], "us": "/slip/"}, "dream": {"zh": "梦；梦想", "phrases": [["dream come true", "梦想成真"], ["daydream", "白日梦"]], "scene": ["book", "We are such stuff / As dreams are made on; and our little life / Is rounded with a sleep.", "我们都是梦一样的材料，我们短暂的一生，被一场睡眠所环绕。", "莎士比亚《暴风雨》The Tempest（第四幕第一场）", "https://www.gutenberg.org/ebooks/23042"], "dlg": ["What did you dream about last night?", "I dreamed I could fly over the ocean!", "I dreamed the sandwich is my uncle."], "us": "/drim/"}, "experience": {"zh": "经历；经验", "phrases": [["learn from experience", "从经验中学习"], ["a fun experience", "一次有趣的经历"]], "scene": ["ai", "Your brain is a scrapbook of experiences. The first time you rode a bike, fell, and got back up — your brain saved that page.", "大脑是一本经历的剪贴簿。第一次骑车、摔倒、再爬起来——大脑把这一页好好保存了下来。"], "dlg": ["How was your first camping trip?", "It was a great experience! We saw so many stars.", "It was a great refrigerator."], "us": "/ɪkˈspɪriəns/"}, "understand": {"zh": "理解；明白", "phrases": [["I understand", "我明白了"], ["easy to understand", "容易理解"]], "scene": ["ai", "A dog can understand about 165 words, scientists say. Your brain? Tens of thousands — and you're learning more right now!", "科学家说，狗大约能听懂165个词。你的大脑呢？几万个——而且你此刻正在学更多！"], "dlg": ["Do you understand the homework?", "Yes, the teacher explained it clearly.", "Yes, the homework is a fish."], "us": "/ˌʌndɚˈstænd/"}, "hungry": {"zh": "饿的", "phrases": [["hungry as a wolf", "饿得像狼一样"], ["hungry for knowledge", "渴求知识"]], "scene": ["ai", "Your stomach sends a \"hungry\" message to your brain. Your brain sends back: \"Find snacks.\" Your legs walk to the kitchen. Teamwork!", "胃给大脑发\"饿了\"的消息，大脑回复：\"去找零食。\"双腿就走向了厨房。真是团队合作！"], "dlg": ["I'm so hungry!", "Let's have some sandwiches for lunch.", "Let's go to sleep on the roof."], "us": "/ˈhʌŋɡri/"}, "blood": {"zh": "血液", "phrases": [["blood type", "血型"], ["in your blood", "天生的；与生俱来"]], "scene": ["ai", "Your heart pumps blood all around your body in about one minute. A drop of blood takes a faster trip than a roller coaster ride!", "心脏大约一分钟就能把血液送遍全身。一滴血的旅程比坐一趟过山车还快！"], "dlg": ["Why do we need blood?", "It carries oxygen and food to every part of the body.", "It makes our hair grow purple."], "us": "/blʌd/"}, "eat": {"zh": "吃", "phrases": [["eat out", "出去吃饭"], ["eat your words", "收回说过的话"]], "scene": ["ai", "\"You are what you eat,\" said Mom. The kid looked at his plate of noodles and said, \"So I'm long and wiggly?\"", "\"吃什么就像什么。\"妈妈说。孩子看着盘子里的面条：\"所以我又长又会扭？\""], "dlg": ["What do you want to eat for dinner?", "Noodles with vegetables, please!", "A blue bicycle, please!"], "us": "/it/"}, "computer": {"zh": "电脑", "phrases": [["computer game", "电脑游戏"], ["like a computer", "像电脑一样"]], "scene": ["ai", "People call the brain a computer, but no computer gets bored, falls in love, or laughs at a silly joke. Your brain is way cooler.", "人们说大脑像电脑，但没有电脑会觉得无聊、会爱上谁、会被一个傻笑话逗乐。你的大脑酷多了。"], "dlg": ["How do you find a word in the dictionary so fast?", "I use the computer to search for it.", "I ask my shoes."], "us": "/kəmˈpjutɚ/"}, "dog": {"zh": "狗", "phrases": [["every dog has its day", "人人都有出头之日"], ["rain cats and dogs", "下倾盆大雨"]], "scene": ["proverb", "Every dog has its day.", "凡人皆有得意日。", "英语谚语", ""], "dlg": ["Whose dog is this?", "It's my neighbor's dog. His name is Max.", "It's the moon's dog."], "us": "/dɔɡ/"}, "disease": {"zh": "疾病", "phrases": [["heart disease", "心脏病"], ["prevent disease", "预防疾病"]], "scene": ["ai", "Washing your hands with soap for 20 seconds — about as long as singing \"Happy Birthday\" twice — helps stop many diseases from spreading.", "用肥皂洗手20秒——差不多是唱两遍《生日快乐》的时间——能阻止很多疾病传播。"], "dlg": ["Why do doctors study so hard?", "To learn how to treat diseases and help people.", "To learn how to fly kites."], "us": "/dɪˈziz/"}, "nerve": {"zh": "神经；勇气", "phrases": [["get on my nerves", "让我心烦"], ["lose your nerve", "失去勇气"]], "scene": ["ai", "If you laid out all the nerves in your body end to end, they would stretch for many thousands of kilometers. You are wired like a city!", "如果把你全身的神经首尾相接，能延伸好几千公里。你就像一座布满电线的城市！"], "dlg": ["Why did I feel the pin prick so fast?", "Nerves in your skin sent a message to your brain.", "Your sock told your brain."], "us": "/nɝv/"}, "different": {"zh": "不同的", "phrases": [["make a difference", "产生影响；起作用"], ["different from", "和……不同"]], "scene": ["book", "It's no use going back to yesterday, because I was a different person then.", "回到昨天是没有用的，因为那时我是另一个人了。", "Lewis Carroll《爱丽丝梦游仙境》（1865）第10章", "https://www.gutenberg.org/ebooks/11"], "dlg": ["Are these two pictures the same?", "No, they're different. One cat has a hat.", "No, they're Wednesday."], "us": "/ˈdɪfɚənt/"}, "time": {"zh": "时间；次", "phrases": [["once upon a time", "从前"], ["time flies", "光阴似箭"]], "scene": ["book", "It was the best of times, it was the worst of times.", "那是最好的时代，那是最坏的时代。", "狄更斯《双城记》A Tale of Two Cities（1859）开篇", "https://www.gutenberg.org/ebooks/98"], "dlg": ["What time is it?", "It's three o'clock. Time for a snack!", "It's a big yellow duck."], "us": "/taɪm/"}, "human": {"zh": "人类；人的", "phrases": [["human being", "人"], ["human nature", "人性"]], "scene": ["ai", "Humans are the only animals that cook their food, write stories, and argue about whether pineapple belongs on pizza.", "人类是唯一会做饭、会写故事、还会为菠萝该不该放在披萨上争论的动物。"], "dlg": ["What makes the human brain special?", "It can think, plan, and imagine new things.", "It can turn into a pumpkin."], "us": "/ˈhjumən/"}, "create": {"zh": "创造", "phrases": [["create something new", "创造新东西"], ["create a story", "编一个故事"]], "scene": ["ai", "Every song, painting, and invention started as a tiny spark in someone's brain. What will your brain create today?", "每一首歌、每一幅画、每一个发明，都始于某人大脑里的一点火花。今天你的大脑会创造什么呢？"], "dlg": ["What are you doing with the clay?", "I'm creating a little dinosaur!", "I'm creating a rainy Thursday."], "us": "/kriˈeɪt/"}, "work": {"zh": "工作；起作用", "phrases": [["work out", "锻炼；解决"], ["hard work pays off", "努力会有回报"]], "scene": ["ai", "Your brain never stops working — even when you're asleep, it's busy sorting your memories like a librarian at night.", "你的大脑从不停工——就算睡着了，它也像夜里的图书管理员一样忙着整理记忆。"], "dlg": ["Does this flashlight work?", "No, I think it needs new batteries.", "No, it is a tiny horse."], "us": "/wɝk/"}, "remember": {"zh": "记得", "phrases": [["remember to", "记得去做"], ["if I remember rightly", "如果我没记错的话"]], "scene": ["movie", "Remember who you are.", "记住你是谁。", "电影《狮子王》The Lion King（1994），木法沙", "https://en.wikipedia.org/wiki/The_Lion_King"], "dlg": ["Don't forget your umbrella!", "Thanks, I'll remember to take it.", "Thanks, I'll remember to eat it."], "us": "/rɪˈmɛmbɚ/"}, "happy": {"zh": "快乐的", "phrases": [["happy-go-lucky", "无忧无虑的"], ["happy birthday", "生日快乐"]], "scene": ["song", "If you're happy and you know it, clap your hands!", "如果你感到幸福你就拍拍手！", "英文儿歌《If You're Happy and You Know It》（传统儿歌）", "https://en.wikipedia.org/wiki/If_You%27re_Happy_and_You_Know_It"], "dlg": ["You're smiling a lot today!", "I'm happy because we're going to the zoo!", "I'm happy because the table is a fish."], "us": "/ˈhæpi/"}, "fear": {"zh": "恐惧；害怕", "phrases": [["fear of the dark", "怕黑"], ["for fear of", "唯恐"]], "scene": ["speech", "The only thing we have to fear is fear itself.", "我们唯一需要恐惧的，是恐惧本身。", "富兰克林·罗斯福 第一次就职演说（1933）", "https://en.wikipedia.org/wiki/First_inauguration_of_Franklin_D._Roosevelt"], "dlg": ["Are you afraid of the dark?", "A little, but a night-light helps me feel brave.", "A little, but bananas are yellow."], "us": "/fɪr/"}, "imagine": {"zh": "想象", "phrases": [["imagine that!", "想想看！真没想到！"], ["use your imagination", "发挥你的想象力"]], "scene": ["ai", "Close your eyes and imagine a purple elephant. Your brain just made something that doesn't exist. That's a superpower!", "闭上眼睛，想象一头紫色的大象。你的大脑刚刚造出了一个不存在的东西——这就是超能力！"], "dlg": ["What would you do with a magic wand?", "I would imagine a world with no homework!", "I would imagine my socks are tired."], "us": "/ˌɪˈmædʒən/"}, "look": {"zh": "看；看起来", "phrases": [["look after", "照顾"], ["look forward to", "期待"]], "scene": ["ai", "Look at a cloud for one minute. Your brain will find a dragon, a rabbit, or a face. Brains love to find patterns — even in the sky!", "盯着一朵云看一分钟，大脑会找到一条龙、一只兔子或一张脸。大脑最爱找规律——连天上也不放过！"], "dlg": ["I'm going to the store. Can you look after your sister?", "Sure, I'll take good care of her.", "Sure, I'll look after the moon."], "us": "/lʊk/"}, "see": {"zh": "看见", "phrases": [["seeing is believing", "眼见为实"], ["see you later", "回头见"]], "scene": ["proverb", "Seeing is believing.", "眼见为实。", "英语谚语", ""], "dlg": ["Can you see the rainbow?", "Yes! It's over the hill.", "Yes! It's inside my soup."], "us": "/si/"}, "use": {"zh": "使用", "phrases": [["make use of", "利用"], ["it's no use", "没用的"]], "scene": ["ai", "A myth says we only use 10% of our brains. Brain scans show we use all of it — just not all at the same time, like rooms in a house.", "有个说法称我们只用了大脑的10%。脑部扫描显示我们用到了全部——只是不同时用，就像家里的各个房间。"], "dlg": ["How do I open this jar?", "Use a towel to help you twist the lid.", "Use a song to help you twist the lid."], "us": "/jus/"}, "people": {"zh": "人们", "phrases": [["people person", "善于交际的人"], ["young people", "年轻人"]], "scene": ["ai", "People's brains are wired to notice faces. That's why you can see a \"face\" in a power outlet or the front of a car!", "人的大脑天生爱注意面孔。所以你会在插座或汽车正面上\"看到\"一张脸！"], "dlg": ["Why is the park so crowded today?", "Lots of people came to see the festival.", "Lots of chairs came to dance."], "us": "/ˈpipəl/"}, "gland": {"zh": "腺体", "phrases": [["sweat gland", "汗腺"], ["oil gland", "油脂腺"]], "scene": ["ai", "A beaver combs special oil from its glands into its fur, like a raincoat it makes itself. No umbrella needed!", "河狸把腺体分泌的油梳进皮毛里，就像自己做了一件雨衣。根本不需要雨伞！"], "dlg": ["How does a beaver keep its fur dry?", "It spreads oil from a special gland onto its fur.", "It hangs its fur on a clothesline."], "us": "/ɡlænd/"}, "undercoat": {"zh": "底层绒毛", "phrases": [["thick undercoat", "厚厚的底绒"], ["winter undercoat", "冬季底绒"]], "scene": ["ai", "Under its long shiny hairs, a beaver wears a soft undercoat — like secret pajamas that keep it warm in icy water.", "在长长的亮毛下面，河狸穿着一层柔软的底绒——像一套秘密睡衣，让它在冰水里也暖暖的。"], "dlg": ["Why doesn't the beaver feel cold in winter?", "Its thick undercoat traps warm air next to its skin.", "It drinks hot soup under the ice."], "us": "/ˈʌndɚˌkoʊt/"}, "cambium": {"zh": "形成层（树皮下的嫩层）", "phrases": [["cambium layer", "形成层"], ["under the bark", "在树皮下面"]], "scene": ["ai", "To a beaver, the cambium under tree bark is like the cream inside a cookie — the best part!", "对河狸来说，树皮下的形成层就像夹心饼干里的奶油——最好吃的部分！"], "dlg": ["What part of the tree do beavers like to eat?", "The soft cambium layer under the bark.", "The shiny metal part."], "us": ""}, "biome": {"zh": "生物群落", "phrases": [["forest biome", "森林生物群落"], ["desert biome", "沙漠生物群落"]], "scene": ["ai", "If Earth were a giant house, each biome would be a room: the desert is the sauna, the tundra is the freezer, and the wetland is the bathtub.", "如果地球是一座大房子，每个生物群落就是一个房间：沙漠是桑拿房，冻原是冰柜，湿地就是浴缸。"], "dlg": ["What kind of biome do beavers live in?", "Wetlands and forests with rivers and ponds.", "The hot, dry desert with no water."], "us": "/ˈbaɪˌoʊm/"}, "adaptation": {"zh": "适应；适应性特征", "phrases": [["a clever adaptation", "巧妙的适应特征"], ["adaptation to the cold", "对寒冷的适应"]], "scene": ["ai", "A beaver's see-through eyelids are an adaptation — built-in swimming goggles that nature designed long before people did.", "河狸透明的眼睑是一种适应特征——大自然比人类早得多就设计好了内置泳镜。"], "dlg": ["Why do beavers have webbed feet?", "It's an adaptation that helps them swim fast.", "It's a fashion choice for parties."], "us": "/ˌædəpˈteɪʃən/"}, "conservation": {"zh": "保护（自然资源）", "phrases": [["wildlife conservation", "野生动物保护"], ["water conservation", "节约用水"]], "scene": ["ai", "Beavers were once hunted almost everywhere. Thanks to conservation, they are back — and busy fixing rivers again.", "河狸曾在许多地方几乎被猎杀殆尽。多亏了保护工作，它们回来了——又开始忙着修整河流。"], "dlg": ["How can we help wild animals?", "Support conservation and protect their homes.", "Paint all the trees blue."], "us": "/ˌkɑnsɚˈveɪʃən/"}, "synapse": {"zh": "突触", "phrases": [["synapse connection", "突触连接"], ["across the synapse", "跨越突触"]], "scene": ["ai", "Two neurons never quite touch. They pass messages across a tiny gap called a synapse, like friends tossing notes across the classroom.", "两个神经元从不真正碰在一起。它们隔着一个叫突触的小缝隙传递消息，就像同学在教室里互相扔纸条。"], "dlg": ["How do neurons talk to each other?", "They send chemical messages across a synapse.", "They write letters and mail them."], "us": "/ˈsɪæps/"}, "cortex": {"zh": "皮层", "phrases": [["cerebral cortex", "大脑皮层"], ["visual cortex", "视觉皮层"]], "scene": ["ai", "The cortex is the wrinkly outer layer of the brain. If you could flatten it out, it would be about the size of a pillowcase!", "皮层是大脑外面皱巴巴的那一层。要是能把它摊平，大约有一个枕套那么大！"], "dlg": ["Why is the brain so wrinkly?", "The folds let a big cortex fit inside your skull.", "Because it forgot to iron itself."], "us": "/ˈkɔrtɛks/"}, "axon": {"zh": "轴突", "phrases": [["long axon", "长轴突"], ["send along the axon", "沿轴突传递"]], "scene": ["ai", "An axon is a neuron's long cable. Some axons run from your spine all the way to your toes — longer than your arm!", "轴突是神经元的长电缆。有些轴突从脊髓一路延伸到脚趾——比你的胳膊还长！"], "dlg": ["How does a signal travel through a neuron?", "It zooms down the long axon to the next cell.", "It takes a bus to the next cell."], "us": "/ˈækˌsɑn/"}, "hippocampus": {"zh": "海马体", "phrases": [["hippocampus and memory", "海马体与记忆"], ["seahorse shape", "海马形状"]], "scene": ["ai", "The hippocampus got its name because it looks like a seahorse. This little seahorse helps you remember where you put your shoes!", "海马体因为长得像海马而得名。这只\"小海马\"帮你记住鞋子放在哪儿！"], "dlg": ["Which part of the brain helps make new memories?", "The hippocampus helps store new memories.", "The elbow stores new memories."], "us": "/ˌhɪpoʊˈkæmpəs/"}, "receptor": {"zh": "受体；感受器", "phrases": [["pain receptor", "痛觉感受器"], ["taste receptor", "味觉受体"]], "scene": ["ai", "Your tongue has receptors for sweet, sour, salty, bitter and umami. Ice cream lights up the sweet ones like a fireworks show!", "舌头上有感受甜、酸、咸、苦和鲜味的受体。冰淇淋会让\"甜味受体\"像放烟花一样亮起来！"], "dlg": ["How does my tongue know candy is sweet?", "Taste receptors send a message to your brain.", "The candy tells your ears."], "us": "/riˈsɛptɚ/"}, "spike": {"zh": "尖峰；（神经）放电脉冲", "phrases": [["a spike in prices", "价格飙升"], ["spike of activity", "活动高峰"]], "scene": ["ai", "When a neuron fires, it makes an electrical spike. Scientists listening with tiny wires say it sounds like popcorn popping!", "神经元放电时会产生一个电脉冲\"尖峰\"。用细电线监听的科学家说，听起来像爆米花在爆！"], "dlg": ["What does a neuron do when it gets enough signals?", "It fires a spike to pass the message on.", "It falls asleep and snores."], "us": "/spaɪk/"}, "electrical": {"zh": "电的", "phrases": [["electrical signal", "电信号"], ["electrical storm", "雷暴"]], "scene": ["ai", "Your brain runs on about 20 watts of electrical power — less than many light bulbs, yet it can write poems and solve puzzles.", "你的大脑运行功率约20瓦——比很多灯泡还低，却能写诗、能解谜题。"], "dlg": ["How do messages move through nerves?", "As tiny electrical signals.", "As little paper boats."], "us": "/ɪˈlɛktrɪkəl/"}, "live": {"zh": "生活；居住", "phrases": [["live and learn", "活到老学到老"], ["live up to", "不辜负"]], "scene": ["proverb", "Live and learn.", "活到老，学到老。", "英语谚语", ""], "dlg": ["Where do beavers live?", "They live in lodges in ponds and rivers.", "They live in shoeboxes under the bed."], "us": "/laɪv/"}, "front": {"zh": "前面", "phrases": [["in front of", "在……前面"], ["front door", "前门"]], "scene": ["ai", "A beaver's front teeth are orange because they contain iron. Nature's version of armor-plated tools!", "河狸的门牙是橙色的，因为里面含铁。这是大自然版的\"装甲工具\"！"], "dlg": ["Where should I wait for you?", "Wait in front of the library.", "Wait inside the banana."], "us": "/frʌnt/"}, "diet": {"zh": "饮食", "phrases": [["healthy diet", "健康饮食"], ["go on a diet", "节食"]], "scene": ["ai", "A beaver's diet is mostly bark, leaves and water plants. Imagine a menu with only salad and sticks — every single day!", "河狸主要吃树皮、树叶和水生植物。想象一下，菜单上每天只有沙拉和树枝！"], "dlg": ["What is in a healthy diet?", "Lots of fruit, vegetables and water.", "Only candy and soda."], "us": "/ˈdaɪət/"}};